with d as (select value r from jsonb_array_elements($q$[{"notes":["The noodles need to be fresh and thick (kway teow), sold in the refrigerated section, they're usually stuck together in a slab. If you can only find thin dried rice noodles, use them, but fresh ones give you that lovely charred edge.","The heat and speed are everything here. Once you start cooking, don't stop stirring. A slow char koay teow is a sad char koay teow.","Cockles are traditional, use fresh ones from the fishmonger if you can find them, or tinned ones from the Asian aisle. If you really can't find them, use more prawns instead.","Food safety: Cook mussels, clams and pipis only if they are alive and tightly closed (or close when tapped), and discard any that stay shut after cooking. Cook prawns until pink and opaque."],"steps":[{"text":"Set a large wok over high heat until it's very hot, you'll feel the heat rise from it. Add 1 tbsp of the oil and swirl to coat."},{"text":"Push the noodles into the wok. They'll clump at first, but keep them moving with your spatula, breaking them apart, until they're loosened and just beginning to brown at the edges, about 2 minutes. Push everything to the side of the wok."},{"text":"Add the remaining oil to the empty side. Crack in the eggs and scramble them quickly with the back of your spatula until just set, then mix them through the noodles."},{"text":"Push everything to the side again. Add the garlic to the empty spot and cook, stirring constantly, until fragrant, about 20 seconds. Then add the prawns and cockles, tossing them with the garlic for 1 minute until the prawns turn pink and opaque."},{"text":"Add the soy sauce, dark soy sauce and oyster sauce, tossing everything together. The noodles will darken and smell wonderful, this takes about 1 minute."},{"text":"Add the bean sprouts and spring onions, tossing for another 30 seconds. If using fresh chilli, toss that through now."},{"text":"Taste and add more soy sauce if you need it. Divide between bowls and serve straight away, while it's still hot and the edges are a bit charred."}],"id":"69a6fd73-50ed-41c7-b631-c1c0462261cc"},{"notes":["Make this the day before and reheat gently on the stove; the flavours deepen overnight.","Whole green chillies stay mild if you don't break them open; remove them before serving if you prefer no heat.","Duck makes this special, but chicken thighs work if duck is hard to find. Reduce the cook time to 45 minutes.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"879dd051-b56f-40ef-80a7-b6fa91bfe566"},{"notes":["Make ahead: Roll the dolma up to 1 day ahead and store in the fridge. Cook just before serving.","Room temperature: These are just as good served at room temperature the next day, making them perfect for packed lunches.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"id":"754757cd-b8a5-4b3d-a619-381c821563f3"},{"notes":["Make ahead: prepare the dolma up to the end of step 3, then cover and refrigerate for up to 24 hours before cooking.","Swap the beef for lamb mince for a richer flavour, which some prefer.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"id":"20b66107-5225-4c7f-9681-c1839107cd90"},{"diets":["vegetarian","vegan","no-dairy"],"notes":["Make the hummus up to a day ahead; store it covered in the fridge and bring to room temperature before serving.","Toast your own pine nuts in a dry pan over medium heat for 2–3 minutes if you have time, it makes a real difference.","This is just as good made with tinned chickpeas as it would be with soaked dried ones."],"id":"19ad88b5-80d7-4ccf-8db7-f40d2c306758"},{"notes":["You can prep the meat sauce ahead and reheat it just before assembling.","If you don't have a deep fryer, use a deep heavy-based pan with at least 8 cm of oil. Use a thermometer to check the temperature.","Some Cape Town versions add sliced cheese or a fried egg, feel free to customize.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"id":"b85aa779-0a72-400c-99ce-200d1dfa5a39"},{"notes":["Holubtsi freeze beautifully. Cool them in their sauce, then freeze in an airtight container for up to three months. Reheat gently in a 160°C oven, covered, for about 30 minutes.","If you can't find buckwheat groats, use cooked white rice or pearl barley instead.","The dish tastes even better the next day, once the flavours have settled together.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Bring a large pot of salted water to the boil. Carefully remove the core from the cabbage with a sharp knife, then place the whole cabbage in the boiling water. After 8–10 minutes, gently peel away the softened outer leaves and set aside on a clean kitchen towel. Repeat until you have about 12 large leaves; reserve any remaining cabbage, finely shredded."},{"text":"While the cabbage cools, heat 1 tbsp oil in a frying pan over medium heat. Cook the onion until soft, about 5 minutes, then add the garlic and cook for 1 minute more. Remove from heat and let cool slightly. In a large bowl, combine the cooled onion and garlic with the beef mince, buckwheat, egg, salt and pepper. Mix gently until just combined, don't overwork it."},{"text":"Lay a cabbage leaf on a clean surface. Place about 2 tbsp of the filling near the base of the leaf, fold the sides in, then roll away from you into a tight parcel. Repeat with the remaining leaves and filling."},{"text":"Heat the remaining 1 tbsp oil in a large heavy-based pan over medium-high heat. Arrange the cabbage rolls seam-side down in a single layer (work in batches if needed). Cook for 2–3 minutes until golden on the base, then turn carefully and cook for another 2 minutes. Remove and set aside on a plate."},{"text":"In the same pan, stir together the tomato paste and cook for 1 minute. Add the crushed tomatoes and beef stock, scraping up any brown bits from the base of the pan. Add the caraway seeds if using, and season with salt and pepper. Scatter the reserved shredded cabbage over the base of the pan."},{"text":"Return the cabbage rolls to the pan, nestling them into the sauce, seam-side down. Bring to a gentle simmer, then reduce heat to low. Cover and braise for 60–70 minutes, until the rolls are tender and the sauce is rich and glossy. Serve warm with a generous dollop of sour cream."}],"id":"e3c070d6-f50c-4c56-8c10-04aa5f640045"},{"notes":["Ilish, hilsa fish, is prized for its soft, buttery flesh and its brief monsoon season. If hilsa is impossible to find, use another oily river fish such as Indian salmon or mackerel, though the dish will be subtly different.","The mustard oil is not negotiable. It is the backbone of this dish. Do not substitute.","Serve with steamed rice to catch every drop of the broth."],"steps":[{"text":"Heat the mustard oil in a heavy-bottomed pan over medium heat until it just begins to smoke. This is essential: the pungency mellows into warmth."},{"text":"Add the nigella seeds and let them crackle for a few seconds until fragrant, about 30 seconds."},{"text":"Stir in the turmeric and cook for a few seconds, until fragrant, to release its colour and flavour into the oil."},{"text":"Carefully arrange the fish pieces in the pan. They will sizzle. Let them sit undisturbed for 2 minutes on each side so the flesh firms gently."},{"text":"Add the water and green chillies. Bring to a gentle simmer, until small bubbles break the surface. Add salt."},{"text":"Cover and cook over low heat for about 15 minutes, until the fish is cooked through and flakes easily when tested, and the broth has begun to amalgamate with the oil and turmeric. Turn the thicker pieces halfway through."},{"text":"Taste and adjust salt if needed. Serve hot, with rice. The broth is as important as the fish."}],"id":"15352227-7309-4fe6-8490-fa132b6a6665"},{"notes":["Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large pot or deep frying pan over medium-high heat. Add the chicken pieces, skin-side down, and cook for 3 to 4 minutes until the skin is golden. Flip and cook for another 2 to 3 minutes on the other side. Remove and set aside."},{"text":"Add the onion, potato and carrot to the pot. Stir and cook for 3 to 4 minutes until the vegetables are lightly browned."},{"text":"Return the chicken to the pot and add the water, bringing to a simmer. Cover and cook for 15 to 20 minutes until the potatoes are tender and the chicken is cooked through."},{"text":"Break the curry roux into chunks and stir into the pot until dissolved. Simmer, uncovered, for 3 to 5 minutes, stirring often, until the sauce thickens slightly. Taste and add salt if needed. Serve over steamed rice."}],"id":"038a1ecd-ef5a-4d91-a5de-8fc5fb8b8472"},{"notes":["Sour cream or Greek yoghurt to serve is traditional.","The rolls can be assembled up to a day ahead, wrapped in plastic, and refrigerated. Bring to room temperature before adding the broth and baking.","Leftovers keep well for 3 days in the fridge and reheat gently in a low oven.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"734b91a6-5bde-49f8-84e4-3bd7761ebd13"},{"notes":["The khoresh tastes better the next day. Make it ahead and reheat gently before serving.","If you can't find fresh rhubarb, use frozen; no need to thaw. The stew will be slightly thinner and more sour.","The tahdig is forgiving. If it burns black, you've learned something for next time. If it doesn't form at all, the stew is still worth eating.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat 3 tbsp oil in a large heavy pot over medium-high heat. Working in batches, brown the lamb on all sides, about 8 minutes total. Set aside."},{"text":"Add the onion to the same pot and cook, stirring, until soft and golden, about 8 minutes. Stir in the turmeric and cook for 1 minute until fragrant."},{"text":"Return the lamb to the pot. Add the tomato paste and stir to coat. Pour in the stock, bring to a simmer, then reduce heat to low. Cover and cook for 45 minutes, stirring occasionally."},{"text":"Add the rhubarb pieces and season with salt and pepper. Continue to simmer, covered, for another 30 minutes. The rhubarb should soften and break down slightly, and the lamb should be tender. The stew will taste sharp and rich. Taste and adjust seasoning."},{"text":"While the stew cooks, prepare the rice. Rinse the basmati rice in a sieve under cold running water until the water runs clear. Bring 1 litre of salted water to a boil in a separate pot. Add the rice and stir gently. Boil for about 10 minutes, until the rice is just tender but still has a slight bite. Drain well."},{"text":"Return the drained rice to the pot. Drizzle 2 tbsp of oil or melted butter over the rice and gently fold it in. Make a well in the centre of the rice. Mix the yoghurt (if using) with 1 tbsp oil and spread on the bottom of a small bowl or saucer to place in the well, this helps the tahdig form. Cover the pot tightly with foil, then place the lid on top."},{"text":"Cook over medium heat for 8 to 10 minutes. You should hear a gentle sizzle and smell the toasted rice. This is the tahdig forming. Lower the heat to the lowest setting and cook for another 10 minutes."},{"text":"To serve, spoon the rice onto a platter, breaking up the tahdig gently from the bottom of the pot and scattering it over the top. Pour the khoresh over and around the rice. Serve hot."}],"id":"0ef27bf1-c51d-46c9-aac5-5ee551340676"},{"notes":["Kina is best eaten fresh and raw, buy it the day you plan to cook it. Your fishmonger can crack it open for you.","Rēwena is a traditional Māori sourdough made with a rewena starter (potato ferment). If you can't find it, look for it at a good bakery or make your own.","This is kai moana at its finest, respect the kai and don't overthink it."],"steps":[{"text":"Toast the rēwena bread until golden and crisp on both sides, about 3–4 minutes."},{"text":"Divide the toasted bread between two plates."},{"text":"Spoon the fresh kina roe evenly over each slice of toast, which should be golden and crisp."},{"text":"Season lightly with salt."},{"text":"Serve immediately with lemon wedges on the side to squeeze over."}],"id":"de431990-715c-4c6c-8c35-bd5018ff39a2"},{"notes":["Make the honey syrup up to 2 hours ahead and reheat gently before serving.","Use a good white cheese, feta works, but halloumi won't melt as much. Some people use a mix.","Künefe is best eaten warm and straight away, when the pastry is still crispy."],"steps":[{"text":"Make the honey syrup first so it's ready to pour hot. In a small saucepan, combine the honey, water, lemon juice and cinnamon stick. Bring to a simmer over medium heat until the syrup is bubbling and slightly thickened, then remove from the heat and let it cool slightly while you prepare the pastry."},{"text":"Preheat the oven to 190°C. Gently separate the kataifi pastry strands, they'll come apart easily if you loosen them with your fingers."},{"text":"Pour a thin layer of melted butter into a round baking dish about 20 cm across. Spread half the kataifi strands evenly over the base, pressing gently to form a layer. Drizzle with more butter."},{"text":"Scatter the crumbled cheese and walnuts over the pastry, leaving a small border around the edges."},{"text":"Layer the remaining kataifi strands on top, press down gently, and pour the rest of the melted butter evenly over everything. Bake for 20 to 25 minutes, until the pastry is deep golden and crispy."},{"text":"Remove from the oven and immediately pour the hot honey syrup all over the künefe. It will sizzle and soak into the pastry. Scatter the pistachios on top if using, and serve right away with plenty of napkins."}],"id":"43594dc7-5b36-499a-b234-5bc24b2ce73e"},{"notes":["Leftover soup keeps for 3 days in the fridge. Reheat gently with a splash of water to loosen.","You can use any lentils you've got, red lentils will make it even creamier but break down faster, so check it at 20 minutes.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"12d4b027-90ac-4dca-a469-a505a80847db"},{"notes":["This mole keeps in the fridge for up to 5 days and freezes beautifully for up to 3 months. Make it ahead, it tastes better the next day.","Use the mole with poached chicken, or pour it over enchiladas, turkey or meatballs. A little mole goes a long way.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"steps":[{"text":"Heat 2 tbsp oil in a large, heavy pot over medium heat. Toast the cinnamon stick, cloves and coriander seeds until fragrant, about 1 minute. Add the deseeded chillies, a few at a time, pressing them gently against the bottom of the pot for a few seconds until they release their aroma. Do not burn them. Remove to a bowl."},{"text":"In the same pot, add 2 tbsp oil. Cook the garlic and onion over medium heat, stirring often, until soft and golden, about 8 minutes."},{"text":"Meanwhile, soak the toasted chillies in 500 ml hot water for 10 minutes until very soft. Strain, reserving all the soaking liquid."},{"text":"Add the soaked chillies, raisins, almonds, sesame seeds and torn tortilla to the pot with the garlic and onion. Stir to combine and cook for 3 minutes."},{"text":"Working in batches, transfer the mixture to a blender with 250 ml of the reserved chilli soaking liquid. Blend until completely smooth. Pour through a fine sieve into a clean pot, pressing with the back of a spoon to extract all the mole."},{"text":"Add the remaining reserved soaking liquid (about 250 ml) to the strained mole and stir to combine. Place over medium-low heat and simmer, stirring often, for 20 minutes. The mole should be thick but pourable."},{"text":"Warm the chicken stock in a separate pot. Add 250 ml of the warm stock to the mole and stir well. Continue simmering, stirring often, for 15 minutes. Add the remaining stock, a little at a time, until you reach the consistency you want, it should coat the back of a spoon but flow slowly."},{"text":"Reduce the heat to very low. Add the chocolate and the remaining 2 tbsp oil, stirring constantly until the chocolate is completely melted and incorporated. Taste and add salt as needed. Keep warm until you're ready to serve."},{"text":"Serve the mole poured over cooked chicken, rice or with warm tortillas. Sprinkle with the extra sesame seeds."}],"id":"870eeed3-a64f-40ab-a7ee-f0c79d2d4025"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;